import{_ as a,o as e,c as t,a5 as o}from"./chunks/framework.Cooo9kuv.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"827-批量提取文件名-文件夹名到excel中","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["EXCEL批处理"],"标签":["excel导出","批量处理工具","文件名提取","文件夹名提取","文件清单生成器","文件管理工具"]},"headers":[],"relativePath":"md/EXCEL批处理/827-批量提取文件名-文件夹名到excel中.md","filePath":"md/EXCEL批处理/827-批量提取文件名-文件夹名到excel中.md"}'),i={name:"md/EXCEL批处理/827-批量提取文件名-文件夹名到excel中.md"};function r(n,l,s,c,h,g){return e(),t("div",null,[...l[0]||(l[0]=[o('<h3 id="批量提取文件名-文件夹名到excel中" tabindex="-1">批量提取文件名-文件夹名到excel中 <a class="header-anchor" href="#批量提取文件名-文件夹名到excel中" aria-label="Permalink to &quot;批量提取文件名-文件夹名到excel中&quot;">​</a></h3><p>快速将指定目录下的文件名或文件夹名批量提取并导出到Excel表格中。无论是需要整理大量文件、创建文件清单，还是进行文件管理统计，本工具都能大幅提高您的工作效率，避免手动操作带来的繁琐和错误。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260222230504177177270489514.jpg" alt=""></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260222230504177177270446546.jpg" alt=""></p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><ul><li><strong>批量提取文件名</strong>：支持将指定目录下的所有文件名提取并导出到Excel表格</li><li><strong>批量提取文件夹名</strong>：支持将指定目录下的所有文件夹名提取并导出到Excel表格</li><li><strong>穿透子文件夹</strong>：可选择是否递归处理所有子文件夹中的内容</li><li><strong>自定义导出内容</strong>：可自由选择导出文件的完整路径、无后缀文件名或带后缀文件名</li></ul><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260222230504177177270411079.png" alt=""></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260222230513177177271334404.png" alt=""></p><h3 id="基本操作指南" tabindex="-1">基本操作指南 <a class="header-anchor" href="#基本操作指南" aria-label="Permalink to &quot;基本操作指南&quot;">​</a></h3><h4 id="功能1-文件名到excel" tabindex="-1">功能1：文件名到Excel <a class="header-anchor" href="#功能1-文件名到excel" aria-label="Permalink to &quot;功能1：文件名到Excel&quot;">​</a></h4><ol><li><strong>选择文件夹</strong>：点击「浏览」按钮，选择需要提取文件名的文件夹</li><li><strong>设置处理选项</strong>： <ul><li>勾选「穿透子文件夹」可同时处理所有子文件夹中的文件</li><li>选择需要导出的列信息（至少选择一列）： <ul><li>A列: 完整路径</li><li>B列: 文件名 (无后缀)</li><li>C列: 文件名 (带后缀)</li></ul></li></ul></li><li><strong>设置输出路径</strong>：点击「浏览」按钮，选择Excel文件的保存位置和名称</li><li><strong>开始处理</strong>：点击「开始」按钮，系统将开始提取文件名并导出到Excel</li><li><strong>查看结果</strong>：处理完成后，日志窗口会显示成功信息，可直接打开生成的Excel文件查看结果</li></ol><h4 id="功能2-文件夹名到excel" tabindex="-1">功能2：文件夹名到Excel <a class="header-anchor" href="#功能2-文件夹名到excel" aria-label="Permalink to &quot;功能2：文件夹名到Excel&quot;">​</a></h4><ol><li><strong>选择文件夹</strong>：点击「浏览」按钮，选择需要提取文件夹名的主文件夹</li><li><strong>设置处理选项</strong>： <ul><li>勾选「穿透子文件夹」可同时处理所有嵌套的子文件夹</li><li>选择需要导出的列信息（至少选择一列）： <ul><li>A列: 完整路径</li><li>B列: 文件夹名</li></ul></li></ul></li><li><strong>设置输出路径</strong>：点击「浏览」按钮，选择Excel文件的保存位置和名称</li><li><strong>开始处理</strong>：点击「开始」按钮，系统将开始提取文件夹名并导出到Excel</li><li><strong>查看结果</strong>：处理完成后，日志窗口会显示成功信息，可直接打开生成的Excel文件查看结果</li></ol><h3 id="实际使用场景示例" tabindex="-1">实际使用场景示例 <a class="header-anchor" href="#实际使用场景示例" aria-label="Permalink to &quot;实际使用场景示例&quot;">​</a></h3><h4 id="场景一-文件清单整理" tabindex="-1">场景一：文件清单整理 <a class="header-anchor" href="#场景一-文件清单整理" aria-label="Permalink to &quot;场景一：文件清单整理&quot;">​</a></h4><p><strong>需求</strong>：某公司需要对服务器上的重要文档进行盘点，需要生成一份包含文件名和路径的完整清单。</p><p><strong>操作步骤</strong>：</p><ol><li>打开「功能1: 文件名到Excel」选项卡</li><li>点击「浏览」选择服务器文档根目录</li><li>勾选「穿透子文件夹」选项，确保能获取所有层级的文件</li><li>同时勾选「A列: 完整路径」和「C列: 文件名 (带后缀)」</li><li>设置输出Excel文件名为「服务器文档清单.xlsx」</li><li>点击「开始」按钮，等待处理完成</li><li>打开生成的Excel文件，即可获得完整的文件清单，包含路径和文件名信息</li></ol><h4 id="场景二-项目结构分析" tabindex="-1">场景二：项目结构分析 <a class="header-anchor" href="#场景二-项目结构分析" aria-label="Permalink to &quot;场景二：项目结构分析&quot;">​</a></h4><p><strong>需求</strong>：开发人员需要了解一个复杂项目的文件夹结构，以便快速熟悉项目组织方式。</p><p><strong>操作步骤</strong>：</p><ol><li>打开「功能2: 文件夹名到Excel」选项卡</li><li>点击「浏览」选择项目根目录</li><li>勾选「穿透子文件夹」选项，获取所有层级的文件夹</li><li>勾选「A列: 完整路径」和「B列: 文件夹名」</li><li>设置输出Excel文件名为「项目结构分析.xlsx」</li><li>点击「开始」按钮，等待处理完成</li><li>通过Excel文件可以清晰地查看整个项目的文件夹组织结构，便于分析和理解</li></ol><h4 id="场景三-批量重命名前的准备" tabindex="-1">场景三：批量重命名前的准备 <a class="header-anchor" href="#场景三-批量重命名前的准备" aria-label="Permalink to &quot;场景三：批量重命名前的准备&quot;">​</a></h4><p><strong>需求</strong>：用户需要对大量图片文件进行批量重命名，但在重命名前需要查看所有文件名并进行规划。</p><p><strong>操作步骤</strong>：</p><ol><li>打开「功能1: 文件名到Excel」选项卡</li><li>点击「浏览」选择存放图片的文件夹</li><li>无需勾选「穿透子文件夹」，因为图片都在同一目录</li><li>勾选「B列: 文件名 (无后缀)」和「C列: 文件名 (带后缀)」</li><li>设置输出Excel文件名为「图片命名规划.xlsx」</li><li>点击「开始」按钮，等待处理完成</li><li>在Excel中查看所有图片名称，可以方便地规划新的命名规则，甚至可以在Excel中直接编辑新名称，为后续的批量重命名做准备</li></ol><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ol><li><strong>权限问题</strong>：确保您对要处理的文件夹有足够的访问权限</li><li><strong>文件数量限制</strong>：处理大量文件（10万以上）时，可能会消耗较多系统资源，请确保计算机性能足够</li><li><strong>Excel兼容性</strong>：生成的Excel文件使用.xlsx格式，建议使用Excel 2010或更高版本打开</li><li><strong>路径长度</strong>：Windows系统对文件路径长度有限制，请避免处理路径过深的文件结构</li><li><strong>程序稳定性</strong>：在处理过程中，请勿关闭程序窗口或强制终止进程，以免导致数据不完整</li></ol><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p></blockquote><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><h3 id="q-导出的excel文件为空是什么原因" tabindex="-1">Q: 导出的Excel文件为空是什么原因？ <a class="header-anchor" href="#q-导出的excel文件为空是什么原因" aria-label="Permalink to &quot;Q: 导出的Excel文件为空是什么原因？&quot;">​</a></h3><p>A：请检查以下几点：1) 选择的文件夹是否包含文件或子文件夹；2) 是否正确勾选了导出列选项；3) 是否有足够的文件访问权限</p><h3 id="q-处理大量文件时程序卡顿怎么办" tabindex="-1">Q: 处理大量文件时程序卡顿怎么办？ <a class="header-anchor" href="#q-处理大量文件时程序卡顿怎么办" aria-label="Permalink to &quot;Q: 处理大量文件时程序卡顿怎么办？&quot;">​</a></h3><p>A：程序采用了多线程设计，界面卡顿通常不会影响后台处理。如遇到严重卡顿，建议减少单次处理的文件数量，分批进行处理。</p><h3 id="q-能否修改导出的excel文件格式或编码" tabindex="-1">Q: 能否修改导出的Excel文件格式或编码？ <a class="header-anchor" href="#q-能否修改导出的excel文件格式或编码" aria-label="Permalink to &quot;Q: 能否修改导出的Excel文件格式或编码？&quot;">​</a></h3><p>A：目前程序固定使用.xlsx格式和默认编码。如需其他格式，请在Excel中打开后另存为所需格式。</p><h3 id="q-程序是否支持处理隐藏文件或系统文件" tabindex="-1">Q: 程序是否支持处理隐藏文件或系统文件？ <a class="header-anchor" href="#q-程序是否支持处理隐藏文件或系统文件" aria-label="Permalink to &quot;Q: 程序是否支持处理隐藏文件或系统文件？&quot;">​</a></h3><p>A：默认情况下，程序会跳过隐藏文件和系统文件。</p><h3 id="q-处理完成后找不到生成的excel文件怎么办" tabindex="-1">Q: 处理完成后找不到生成的Excel文件怎么办？ <a class="header-anchor" href="#q-处理完成后找不到生成的excel文件怎么办" aria-label="Permalink to &quot;Q: 处理完成后找不到生成的Excel文件怎么办？&quot;">​</a></h3><p>A：请检查日志窗口中显示的文件保存路径，默认情况下，文件会保存在您选择的文件夹内，文件名为「文件名统计表.xlsx」或「文件夹名统计表.xlsx」。</p><h3 id="📑-程序使用说明" tabindex="-1">📑 程序使用说明 <a class="header-anchor" href="#📑-程序使用说明" aria-label="Permalink to &quot;📑 程序使用说明&quot;">​</a></h3><p><strong>双击快捷方式使用即可</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260222230504177177270424531.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2085.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2085.html</a></p>',47)])])}const d=a(i,[["render",r]]);export{p as __pageData,d as default};
